function createStoryTrail(world){
 const layer=document.createElement('div');layer.className='story-trail';layer.setAttribute('aria-hidden','true');world.append(layer);
 const banner=document.createElement('div');banner.className='mischief-banner';banner.innerHTML='<span></span><span></span>';layer.append(banner);
 const wand=document.createElement('div');wand.className='arrival-spell';wand.innerHTML='<img src="assets/wand-cast-0.svg" alt=""><span class="spell-tip"></span>';layer.append(wand);
 const status=document.createElement('div');status.className='arrival-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');status.hidden=true;world.append(status);
 let pointer={x:.5,y:.55};world.addEventListener('pointerdown',e=>{const r=world.getBoundingClientRect();pointer={x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}},{passive:true});
 let sequenceRAF=0,sequenceLast=0,sequenceTime=0,stages=[];
 function sequenceFrame(now){const delta=Math.min(Math.max(now-sequenceLast,0),100);sequenceLast=now;if(!world.classList.contains('paused')&&!document.hidden)sequenceTime+=delta;while(stages.length&&stages[0].at<=sequenceTime){stages.shift().run()}if(stages.length)sequenceRAF=requestAnimationFrame(sequenceFrame);else sequenceRAF=0}

 const fireworks=document.createElement('canvas');fireworks.className='story-fireworks';fireworks.setAttribute('aria-hidden','true');world.append(fireworks);const c=fireworks.getContext('2d');
 let token=0,running=false,raf=0,elapsed=0,last=0,particles=[],rockets=[],flashes=[],next=0;
 const reduced=()=>matchMedia('(prefers-reduced-motion: reduce)').matches;
 function burst(x,y){flashes.push({x,y,age:0});const count=innerWidth<650?60:90;for(let i=0;i<count;i++){const a=Math.random()*Math.PI*2,z=Math.random()*2-1,ring=Math.sqrt(1-z*z),speed=125+Math.random()*130;particles.push({x,y,vx:Math.cos(a)*speed*ring,vy:Math.sin(a)*speed*ring,age:0,life:1.7+Math.random()*1.1,white:Math.random()>.72,seed:Math.random()*20,trail:[]})}}
 function launch(){const x=innerWidth*(.16+Math.random()*.68),y=innerHeight*(.14+Math.random()*.20);rockets.push({x,y,start:innerHeight*.85,age:0,duration:.8+Math.random()*.3})}
 function frame(now){const dt=Math.min((now-last)/1000,.12)||0;last=now;const w=innerWidth,h=innerHeight,d=Math.min(devicePixelRatio||1,1.5);if(fireworks.width!==Math.round(w*d)||fireworks.height!==Math.round(h*d)){fireworks.width=w*d;fireworks.height=h*d}c.setTransform(d,0,0,d,0,0);c.clearRect(0,0,w,h);
 if(!world.classList.contains('paused')){elapsed+=dt;for(const f of flashes)f.age+=dt;if(running&&elapsed>next){launch();next=elapsed+1.6+Math.random()*.45}for(const r of rockets){r.age+=dt;if(r.age>=r.duration&&!r.done){r.done=true;burst(r.x,r.y)}}for(const p of particles){p.trail.unshift([p.x,p.y]);if(p.trail.length>6)p.trail.pop();p.age+=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=64*dt;p.vx*=Math.exp(-dt*.55);p.vy*=Math.exp(-dt*.12)}}
 rockets=rockets.filter(r=>!r.done);particles=particles.filter(p=>p.age<p.life);c.save();c.globalCompositeOperation='screen';flashes=flashes.filter(f=>f.age<.22);for(const f of flashes){const a=(1-f.age/.22)*.22,g=c.createRadialGradient(f.x,f.y,0,f.x,f.y,85);g.addColorStop(0,`rgba(255,241,207,${a})`);g.addColorStop(1,'rgba(255,232,175,0)');c.fillStyle=g;c.fillRect(f.x-85,f.y-85,170,170)}for(const r of rockets){const q=Math.min(1,r.age/r.duration),y=r.start+(r.y-r.start)*(1-Math.pow(1-q,1.8));c.strokeStyle='rgba(255,231,184,.75)';c.lineWidth=1;c.beginPath();c.moveTo(r.x,y+18);c.lineTo(r.x,y);c.stroke();c.fillStyle='#fff4df';c.fillRect(r.x-1,y-1,2,2)}
 for(const p of particles){const fade=Math.pow(1-p.age/p.life,1.2),twinkle=.72+.28*Math.sin(p.age*27+p.seed);for(let k=p.trail.length-1;k>=0;k--){const [x,y]=p.trail[k];c.globalAlpha=fade*twinkle*(1-k/7)*.8;c.strokeStyle=p.white?'#fff8e5':'#eac288';c.lineWidth=k? .65:1.1;c.beginPath();c.moveTo(x,y);const prev=p.trail[k+1]||[x-p.vx*.018,y-p.vy*.018];c.lineTo(...prev);c.stroke()}if(p.age<.08){c.globalAlpha=(1-p.age/.08)*.85;c.fillStyle='#fff4ce';c.beginPath();c.arc(p.x,p.y,1.8,0,7);c.fill()}}c.restore();
 if(running||particles.length||rockets.length)raf=requestAnimationFrame(frame);else{raf=0;c.clearRect(0,0,w,h)}}
 function fire(on){const starting=on&&!running;running=on&&!reduced();if(!running)rockets=[];if(running&&starting){burst(innerWidth*.26,innerHeight*.23);launch();next=elapsed+1.5}if(running&&!raf){last=performance.now();raf=requestAnimationFrame(frame)}}
 function cancel(){token++;cancelAnimationFrame(sequenceRAF);sequenceRAF=0;stages=[];layer.querySelectorAll('.map-step').forEach(el=>el.remove());layer.dataset.phase='idle';banner.classList.remove('visible');wand.classList.remove('casting');status.hidden=true;document.body.classList.remove('casting-spell');document.body.style.removeProperty('--spell-cursor');fire(false)}
 function arrive(id,reveal){cancel();const mine=token;if(reduced()){reveal();return}const w=world.clientWidth,h=world.clientHeight;const banners={nift:['I solemnly swear','I am up to no good'],sant:['A little craft','A whole new world'],janitri:['Listening first','Designing for care'],me:['Mischief','Managed']};const words=banners[id]||['Mischief','Managed'];banner.querySelectorAll('span').forEach((el,i)=>el.textContent=words[i]);status.hidden=false;status.textContent='Follow the footsteps.';layer.dataset.phase='footsteps';
 const schedule=(at,run)=>stages.push({at,run:()=>{if(token===mine)run()}});
 // Alternating prints settle fully before the wand begins. All times are milliseconds after arrival.
 for(let i=0;i<6;i++){const q=i/5,v=1-q,side=i%2?-1:1;const x=(v*v*.10+2*v*q*.30+q*q*.23)*w+side*(w<650?15:23),y=(v*v*.82+2*v*q*.58+q*q*.30)*h;const dx=2*v*(.30-.10)+2*q*(.23-.30),dy=2*v*(.58-.82)+2*q*(.30-.58),angle=Math.atan2(dx*w,-dy*h)*180/Math.PI;const step=document.createElement('span');step.className='map-step';step.dataset.tone=i%2?'beige':'orange';step.style.cssText=`left:${x}px;top:${y}px;--step-scale:${1.1-q*.20};--step-side:${side};--step-turn:${angle}deg`;layer.append(step);schedule(i*440,()=>step.classList.add('visible'))}
 schedule(2650,()=>{layer.dataset.phase='spell';status.textContent='A little magic…';wand.style.left=Math.max(100,w*.23)+'px';wand.style.top=(h*.31)+'px';wand.classList.add('casting');worldSound.paper()});
 schedule(3650,()=>{wand.classList.remove('casting');layer.dataset.phase='fireworks';status.textContent='Your chapter is about to unfold.';fire(true);layer.querySelectorAll('.map-step').forEach(el=>el.classList.add('fading'))});
 schedule(4200,()=>{layer.dataset.phase='banner';status.hidden=true;banner.querySelectorAll('span').forEach((el,i)=>{el.textContent=words[i]});banner.classList.add('visible')});
 schedule(6500,()=>banner.classList.remove('visible'));
 schedule(7100,()=>{layer.dataset.phase='chapter';status.hidden=true;fire(false);layer.querySelectorAll('.map-step').forEach(el=>el.remove());reveal()});
 sequenceTime=0;sequenceLast=performance.now();sequenceRAF=requestAnimationFrame(sequenceFrame);
 }
 return{arrive,cancel,fire};
}
